from pathlib import Path
WORKSPACE_ROOT=Path(__file__).resolve().parents[1]
audit_columns='OLUSTURMA_TARIHI TIMESTAMP DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL, OLUSTURAN_KULLANICI_ID NUMBER(19) DEFAULT 0 NOT NULL, GUNCELLEME_TARIHI TIMESTAMP, GUNCELLEYEN_KULLANICI_ID NUMBER(19)'
